--
-- Name: analysis_attempt; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."analysis_attempt" (
    "id" "uuid" DEFAULT "public"."uuidv7"() NOT NULL,
    "report_id" "uuid" NOT NULL,
    "attempt_number" smallint NOT NULL,
    "status" "public"."analysis_attempt_status" NOT NULL,
    "requested_by_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "worker_id" "text",
    "claimed_at" timestamp with time zone,
    "lease_renewed_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "cancel_requested_at" timestamp with time zone,
    "failure_reason" "public"."analysis_failure_reason",
    "failure_detail" "text",
    "reaped_by_worker_id" "text",
    "notification_email_sent_at" timestamp with time zone,
    "notification_claimed_at" timestamp with time zone,
    "notification_claimed_by_worker_id" "text",
    "notification_attempts" integer DEFAULT 0 NOT NULL,
    "required_contract_version" smallint DEFAULT 1 NOT NULL,
    "worker_git_sha" "text",
    CONSTRAINT "analysis_attempt_attempt_number_range" CHECK ((("attempt_number" >= 1) AND ("attempt_number" <= 5))),
    CONSTRAINT "analysis_attempt_cancel_requested_at_after_created_at" CHECK ((("cancel_requested_at" IS NULL) OR ("cancel_requested_at" >= "created_at"))),
    CONSTRAINT "analysis_attempt_canceled_is_not_notified" CHECK ((("notification_claimed_at" IS NULL) OR ("status" <> 'canceled'::"public"."analysis_attempt_status"))),
    CONSTRAINT "analysis_attempt_canceled_requires_request" CHECK ((("status" <> 'canceled'::"public"."analysis_attempt_status") OR ("cancel_requested_at" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_claimed_at_after_created_at" CHECK ((("claimed_at" IS NULL) OR ("claimed_at" >= "created_at"))),
    CONSTRAINT "analysis_attempt_failure_reason_iff_failed" CHECK ((("status" = 'failed'::"public"."analysis_attempt_status") = ("failure_reason" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_finished_at_after_created_at" CHECK ((("finished_at" IS NULL) OR ("finished_at" >= "created_at"))),
    CONSTRAINT "analysis_attempt_finished_at_after_lease_renewed" CHECK ((("finished_at" IS NULL) OR ("lease_renewed_at" IS NULL) OR ("finished_at" >= "lease_renewed_at"))),
    CONSTRAINT "analysis_attempt_finished_at_iff_terminal" CHECK ((("status" = ANY (ARRAY['succeeded'::"public"."analysis_attempt_status", 'failed'::"public"."analysis_attempt_status", 'canceled'::"public"."analysis_attempt_status"])) = ("finished_at" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_lease_renewed_after_claimed_at" CHECK ((("lease_renewed_at" IS NULL) OR ("claimed_at" IS NULL) OR ("lease_renewed_at" >= "claimed_at"))),
    CONSTRAINT "analysis_attempt_lease_renewed_after_created_at" CHECK ((("lease_renewed_at" IS NULL) OR ("lease_renewed_at" >= "created_at"))),
    CONSTRAINT "analysis_attempt_notification_attempts_iff_claimed" CHECK ((("notification_attempts" > 0) = ("notification_claimed_at" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_notification_attempts_non_negative" CHECK (("notification_attempts" >= 0)),
    CONSTRAINT "analysis_attempt_notification_claim_requires_finished" CHECK ((("notification_claimed_at" IS NULL) OR ("finished_at" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_notification_claimed_by_iff_claimed" CHECK ((("notification_claimed_at" IS NOT NULL) = ("notification_claimed_by_worker_id" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_notification_requires_finished" CHECK ((("notification_email_sent_at" IS NULL) OR ("finished_at" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_notification_sent_requires_claim" CHECK ((("notification_email_sent_at" IS NULL) OR ("notification_claimed_at" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_pending_is_unclaimed" CHECK ((("status" <> 'pending'::"public"."analysis_attempt_status") OR (("worker_id" IS NULL) AND ("claimed_at" IS NULL) AND ("lease_renewed_at" IS NULL)))),
    CONSTRAINT "analysis_attempt_processing_is_claimed" CHECK ((("status" <> 'processing'::"public"."analysis_attempt_status") OR (("worker_id" IS NOT NULL) AND ("claimed_at" IS NOT NULL) AND ("lease_renewed_at" IS NOT NULL) AND ("finished_at" IS NULL)))),
    CONSTRAINT "analysis_attempt_required_contract_version_positive" CHECK (("required_contract_version" >= 1)),
    CONSTRAINT "analysis_attempt_worker_git_sha_format" CHECK (("worker_git_sha" ~ '^[0-9a-f]{40}$'::"text"))
);


ALTER TABLE "public"."analysis_attempt" OWNER TO "postgres";

--
-- Name: TABLE "analysis_attempt"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE "public"."analysis_attempt" IS 'The queue and state machine between the web app and the workers. Checks cannot be deferred, so a transition to a terminal status must set status, finished_at and failure_reason in one UPDATE.';


--
-- Name: COLUMN "analysis_attempt"."worker_id"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt"."worker_id" IS 'The supervising worker''s identity, unique per process — not per host. A restarted container must
       not reuse its predecessor''s id, or the ownership guard on every terminal write stops
       distinguishing this supervisor from a dead one.';


--
-- Name: COLUMN "analysis_attempt"."lease_renewed_at"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt"."lease_renewed_at" IS 'When a worker last confirmed it was still supervising this attempt and would still reach a verdict for it.';


--
-- Name: COLUMN "analysis_attempt"."notification_claimed_at"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt"."notification_claimed_at" IS 'Set by a worker before it sends the notification email, so a second worker cannot claim the
       same row. Left in place if the send fails, so the row stays claimed until it expires — that
       expiry is what lets a later sweep retry the send instead of the claim silently losing it.';


--
-- Name: COLUMN "analysis_attempt"."notification_claimed_by_worker_id"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt"."notification_claimed_by_worker_id" IS 'Debugging only, symmetric with reaped_by_worker_id.';


--
-- Name: COLUMN "analysis_attempt"."notification_attempts"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt"."notification_attempts" IS 'Incremented by the claim, before the send is attempted. Bounds retries: once it reaches the
       configured maximum the row stops being claimed, however stale its claim, so a permanently
       undeliverable address costs a fixed number of provider requests rather than an unbounded
       retry loop.';


--
-- Name: COLUMN "analysis_attempt"."required_contract_version"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt"."required_contract_version" IS 'The lowest worker contract version that can safely claim this row, so an old worker leaves
       an attempt it cannot handle in the queue instead of claiming and failing it.';


--
-- Name: COLUMN "analysis_attempt"."worker_git_sha"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt"."worker_git_sha" IS 'The commit the claiming worker was built from, set at claim. Null for a build that does not know its own, such as a local one.';


--
-- Name: report; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."report" (
    "id" "uuid" DEFAULT "public"."uuidv7"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "created_by_user_id" "uuid",
    "name" "text" NOT NULL,
    "site_name" "text",
    "counts_basis" "public"."counts_basis",
    "monthly_counts" "jsonb",
    "unit_system" "public"."unit_system" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "report_counts_all_or_none" CHECK ((("counts_basis" IS NULL) = ("monthly_counts" IS NULL))),
    CONSTRAINT "report_deleted_at_after_created_at" CHECK ((("deleted_at" IS NULL) OR ("deleted_at" >= "created_at"))),
    CONSTRAINT "report_monthly_counts_is_object" CHECK ((("jsonb_typeof"("monthly_counts") = 'object'::"text") AND ("monthly_counts" <> '{}'::"jsonb")))
);


ALTER TABLE "public"."report" OWNER TO "postgres";

--
-- Name: COLUMN "report"."counts_basis"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."report"."counts_basis" IS 'Whether monthly_counts counts diners or meals. NULL when the uploader chose not to give counts.';


--
-- Name: COLUMN "report"."monthly_counts"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."report"."monthly_counts" IS 'Month to diner or meal count, keyed YYYY-MM. Which of the two is counts_basis. NULL when the uploader chose not to give counts.';


--
-- Name: analysis_attempt_finding; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."analysis_attempt_finding" (
    "analysis_attempt_id" "uuid" NOT NULL,
    "position" integer NOT NULL,
    "quality_check" "public"."quality_check" NOT NULL,
    "status" "public"."diagnostic_status" NOT NULL,
    "message" "text" NOT NULL,
    "sample_values" "text"[] NOT NULL,
    CONSTRAINT "analysis_attempt_finding_message_not_empty" CHECK (("message" <> ''::"text")),
    CONSTRAINT "analysis_attempt_finding_position_non_negative" CHECK (("position" >= 0)),
    CONSTRAINT "analysis_attempt_finding_sample_values_at_most_5" CHECK (("cardinality"("sample_values") <= 5)),
    CONSTRAINT "analysis_attempt_finding_status_is_warning_or_error" CHECK (("status" = ANY (ARRAY['warning'::"public"."diagnostic_status", 'error'::"public"."diagnostic_status"])))
);


ALTER TABLE "public"."analysis_attempt_finding" OWNER TO "postgres";

--
-- Name: TABLE "analysis_attempt_finding"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE "public"."analysis_attempt_finding" IS 'The warning and error findings the customer''s PDF lists for a succeeded attempt, written in the same transaction as its success. No rows means no warnings. Messages name the customer''s products, so they are deleted with the attempt.';


--
-- Name: COLUMN "analysis_attempt_finding"."position"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt_finding"."position" IS 'Zero-based place in the PDF''s list, which is the order to show them in.';


--
-- Name: analysis_attempt_llm_usage; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."analysis_attempt_llm_usage" (
    "analysis_attempt_id" "uuid" NOT NULL,
    "operation" "public"."llm_operation" NOT NULL,
    "requested_model" "text" NOT NULL,
    "served_model" "text",
    "calls" integer NOT NULL,
    "requests" integer NOT NULL,
    "failed_requests" integer NOT NULL,
    "rate_limited_requests" integer NOT NULL,
    "truncated_calls" integer NOT NULL,
    "input_tokens" integer NOT NULL,
    "cached_input_tokens" integer NOT NULL,
    "output_tokens" integer NOT NULL,
    "cost_micro_usd" integer NOT NULL,
    CONSTRAINT "analysis_attempt_llm_usage_cached_input_tokens_within_input" CHECK ((("cached_input_tokens" >= 0) AND ("cached_input_tokens" <= "input_tokens"))),
    CONSTRAINT "analysis_attempt_llm_usage_calls_positive" CHECK (("calls" >= 1)),
    CONSTRAINT "analysis_attempt_llm_usage_counts_non_negative" CHECK ((("truncated_calls" >= 0) AND ("output_tokens" >= 0) AND ("cost_micro_usd" >= 0))),
    CONSTRAINT "analysis_attempt_llm_usage_requested_model_format" CHECK (("requested_model" ~ '^[a-z0-9][a-z0-9._:-]{0,99}$'::"text")),
    CONSTRAINT "analysis_attempt_llm_usage_requests_ordered" CHECK ((("requests" >= "failed_requests") AND ("failed_requests" >= "rate_limited_requests") AND ("rate_limited_requests" >= 0))),
    CONSTRAINT "analysis_attempt_llm_usage_served_model_format" CHECK (("served_model" ~ '^[a-z0-9][a-z0-9._:-]{0,99}$'::"text")),
    CONSTRAINT "analysis_attempt_llm_usage_successful_requests_at_most_calls" CHECK ((("requests" - "failed_requests") <= "calls")),
    CONSTRAINT "analysis_attempt_llm_usage_truncated_calls_at_most_calls" CHECK (("truncated_calls" <= "calls"))
);


ALTER TABLE "public"."analysis_attempt_llm_usage" OWNER TO "postgres";

--
-- Name: TABLE "analysis_attempt_llm_usage"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE "public"."analysis_attempt_llm_usage" IS 'One row per attempt, operation and requested model, written with its analysis_attempt_telemetry row. A report''s cost is the sum over its attempts, since a retry spends again. Outlives the attempt, report and organization it describes, and holds no personal data.';


--
-- Name: COLUMN "analysis_attempt_llm_usage"."served_model"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt_llm_usage"."served_model" IS 'The model that answered, as OpenAI resolved the requested one. Null when no call got a response; the latest if it changed mid-run.';


--
-- Name: COLUMN "analysis_attempt_llm_usage"."calls"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt_llm_usage"."calls" IS 'Calls the analysis made to its LLM client. A call retries, so it can span several requests, and stops at its first successful one.';


--
-- Name: COLUMN "analysis_attempt_llm_usage"."requests"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt_llm_usage"."requests" IS 'HTTP requests to OpenAI, retries included.';


--
-- Name: COLUMN "analysis_attempt_llm_usage"."input_tokens"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt_llm_usage"."input_tokens" IS 'Including cached_input_tokens, as OpenAI counts them.';


--
-- Name: COLUMN "analysis_attempt_llm_usage"."cost_micro_usd"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt_llm_usage"."cost_micro_usd" IS 'At the list price the run knew, computed from this row''s tokens. Tokens are stored beside it, so a price correction is an UPDATE.';


--
-- Name: analysis_attempt_quality_check; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."analysis_attempt_quality_check" (
    "analysis_attempt_id" "uuid" NOT NULL,
    "quality_check" "public"."quality_check" NOT NULL,
    "status" "public"."diagnostic_status" NOT NULL,
    "findings" integer NOT NULL,
    CONSTRAINT "analysis_attempt_quality_check_findings_positive" CHECK (("findings" >= 1))
);


ALTER TABLE "public"."analysis_attempt_quality_check" OWNER TO "postgres";

--
-- Name: TABLE "analysis_attempt_quality_check"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE "public"."analysis_attempt_quality_check" IS 'How many findings each quality check reported at each status, for an attempt whose report was built. Success rows are kept, so a firing rate has a denominator. Outlives the attempt, report and organization it describes, and holds no personal data.';


--
-- Name: analysis_attempt_telemetry; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE IF NOT EXISTS "public"."analysis_attempt_telemetry" (
    "analysis_attempt_id" "uuid" NOT NULL,
    "report_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "counts_basis" "public"."counts_basis",
    "recorded_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "input_rows" integer,
    "input_kilograms" double precision,
    "input_unique_products" integer,
    "categorization_cache_entries" integer,
    "cache_raw_name_products" integer,
    "cache_cleaned_name_products" integer,
    "llm_matched_products" integer,
    "cache_no_match_products" integer,
    "llm_no_match_products" integer,
    "unrecognized_llm_answers" integer,
    "categorized_rows" integer,
    "categorized_kilograms" double precision,
    "total_co2e_kg" double precision,
    "co2e_kg_per_diner_or_meal" double precision,
    "plant_pct_by_weight" double precision,
    "plant_protein_pct_by_weight" double precision,
    "read_duration_ms" integer,
    "categorize_duration_ms" integer,
    "report_duration_ms" integer,
    "pdf_duration_ms" integer,
    "xlsx_duration_ms" integer,
    "peak_memory_kib" integer NOT NULL,
    CONSTRAINT "analysis_attempt_telemetry_categorization_all_or_none" CHECK (("num_nulls"("cache_raw_name_products", "cache_cleaned_name_products", "llm_matched_products", "cache_no_match_products", "llm_no_match_products", "unrecognized_llm_answers", "categorized_rows", "categorized_kilograms") = ANY (ARRAY[0, 8]))),
    CONSTRAINT "analysis_attempt_telemetry_categorization_requires_input" CHECK ((("categorized_rows" IS NULL) OR ("input_rows" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_telemetry_categorize_duration_requires_read" CHECK ((("categorize_duration_ms" IS NULL) OR ("read_duration_ms" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_telemetry_categorized_rows_at_most_input_rows" CHECK (("categorized_rows" <= "input_rows")),
    CONSTRAINT "analysis_attempt_telemetry_counts_non_negative" CHECK ((("input_rows" >= 0) AND ("input_unique_products" >= 0) AND ("categorization_cache_entries" >= 0) AND ("cache_raw_name_products" >= 0) AND ("cache_cleaned_name_products" >= 0) AND ("llm_matched_products" >= 0) AND ("cache_no_match_products" >= 0) AND ("llm_no_match_products" >= 0) AND ("unrecognized_llm_answers" >= 0) AND ("categorized_rows" >= 0) AND ("read_duration_ms" >= 0) AND ("categorize_duration_ms" >= 0) AND ("report_duration_ms" >= 0) AND ("pdf_duration_ms" >= 0) AND ("xlsx_duration_ms" >= 0))),
    CONSTRAINT "analysis_attempt_telemetry_input_all_or_none" CHECK (("num_nulls"("input_rows", "input_kilograms", "input_unique_products", "categorization_cache_entries") = ANY (ARRAY[0, 4]))),
    CONSTRAINT "analysis_attempt_telemetry_match_types_sum_to_unique_products" CHECK (((("cache_raw_name_products" + "cache_cleaned_name_products") + "llm_matched_products") = "input_unique_products")),
    CONSTRAINT "analysis_attempt_telemetry_pdf_duration_requires_report" CHECK ((("pdf_duration_ms" IS NULL) OR ("report_duration_ms" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_telemetry_peak_memory_kib_positive" CHECK (("peak_memory_kib" > 0)),
    CONSTRAINT "analysis_attempt_telemetry_per_diner_iff_report_and_counts" CHECK ((("co2e_kg_per_diner_or_meal" IS NULL) = (("total_co2e_kg" IS NULL) OR ("counts_basis" IS NULL)))),
    CONSTRAINT "analysis_attempt_telemetry_percentages_in_range" CHECK (((("plant_pct_by_weight" >= (0)::double precision) AND ("plant_pct_by_weight" <= (100)::double precision)) AND (("plant_protein_pct_by_weight" >= (0)::double precision) AND ("plant_protein_pct_by_weight" <= (100)::double precision)))),
    CONSTRAINT "analysis_attempt_telemetry_plant_protein_requires_report" CHECK ((("plant_protein_pct_by_weight" IS NULL) OR ("total_co2e_kg" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_telemetry_quantities_non_negative" CHECK ((("input_kilograms" >= (0)::double precision) AND ("categorized_kilograms" >= (0)::double precision) AND ("total_co2e_kg" >= (0)::double precision) AND ("co2e_kg_per_diner_or_meal" >= (0)::double precision))),
    CONSTRAINT "analysis_attempt_telemetry_report_all_or_none" CHECK (("num_nulls"("total_co2e_kg", "plant_pct_by_weight") = ANY (ARRAY[0, 2]))),
    CONSTRAINT "analysis_attempt_telemetry_report_duration_requires_categorize" CHECK ((("report_duration_ms" IS NULL) OR ("categorize_duration_ms" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_telemetry_report_requires_categorization" CHECK ((("total_co2e_kg" IS NULL) OR ("categorized_rows" IS NOT NULL))),
    CONSTRAINT "analysis_attempt_telemetry_xlsx_duration_requires_pdf" CHECK ((("xlsx_duration_ms" IS NULL) OR ("pdf_duration_ms" IS NOT NULL)))
);


ALTER TABLE "public"."analysis_attempt_telemetry" OWNER TO "postgres";

--
-- Name: TABLE "analysis_attempt_telemetry"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE "public"."analysis_attempt_telemetry" IS 'One row per analysis attempt, written by the worker after the verdict on every ending the child left a telemetry document for. Each column group (input, categorization, report, and each stage time) fills in as its stage finishes, so a killed run keeps a prefix. Outlives the attempt, report and organization it names, and holds no personal data.';


--
-- Name: COLUMN "analysis_attempt_telemetry"."counts_basis"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt_telemetry"."counts_basis" IS 'A copy of the report''s. NULL when the uploader chose not to give counts, and then so is co2e_kg_per_diner_or_meal.';


--
-- Name: COLUMN "analysis_attempt_telemetry"."cache_raw_name_products"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt_telemetry"."cache_raw_name_products" IS 'Unique products the categorization cache had as uploaded. With cache_cleaned_name_products and llm_matched_products, partitions input_unique_products.';


--
-- Name: COLUMN "analysis_attempt_telemetry"."cache_cleaned_name_products"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt_telemetry"."cache_cleaned_name_products" IS 'Unique products the categorization cache had once the LLM cleaned their names.';


--
-- Name: COLUMN "analysis_attempt_telemetry"."cache_no_match_products"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt_telemetry"."cache_no_match_products" IS 'Unique products whose cached category is "No Matches Found". Counted among the cache hits, and their rows are left out of the report.';


--
-- Name: COLUMN "analysis_attempt_telemetry"."unrecognized_llm_answers"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."analysis_attempt_telemetry"."unrecognized_llm_answers" IS 'Cleaned names the LLM answered with something other than a known category. Per unique cleaned name, not per product.';


